import type { PyqPaper } from '../types';
export const main20230131S1: PyqPaper = { id: 'main-2023-01-31-s1', exam: 'JEE Main', year: 2023, session: 'January', date: '2023-01-31', shift: 1, source: 'MathonGo compilation of JEE Main 2023 (31 Jan, Shift 1)', answerSource: 'answer-key', questions: [
{ id: 'main-2023-01-31-s1-Q1', number: 1, subject: 'Physics', chapter: 'Units, Dimensions and Errors', topic: 'Dimensions and Dimensional Formulae', pattern: 'Dimensions of a derived/combined quantity', type: 'single', difficulty: 'Easy',
  question: 'If R, X_L and X_C represent resistance, inductive reactance and capacitive reactance, which of the following is dimensionless?',
  options: ['R X_L X_C', 'R/√(X_L X_C)', 'R/(X_L X_C)', 'R X_L/X_C'], answers: ['R/√(X_L X_C)'],
  solution: 'R, X_L and X_C all have the dimensions of resistance, so R/√(X_L X_C) is dimensionless.' },
{ id: 'main-2023-01-31-s1-Q2', number: 2, subject: 'Physics', chapter: 'Kinematics', topic: 'Projectile Motion', pattern: 'Time of flight from speed at highest point', type: 'single', difficulty: 'Easy',
  question: 'The initial speed of a projectile fired from ground is u. At the highest point of its motion, the speed of the projectile is (√3/2)u. The time of flight of the projectile is:',
  options: ['u/(2g)', 'u/g', '2u/g', '√3u/g'], answers: ['u/g'],
  solution: 'u cosθ = (√3/2)u gives θ = 30°, so T = 2u sinθ/g = u/g.' },
{ id: 'main-2023-01-31-s1-Q3', number: 3, subject: 'Physics', chapter: 'Laws of Motion', topic: 'Newton\'s Laws of Motion', pattern: 'Normal reaction under inclined push on a roller', type: 'single', difficulty: 'Easy',
  question: 'As shown in figure, a 70 kg garden roller is pushed with a force F = 200 N at an angle of 30° with horizontal. The normal reaction on the roller is (Given g = 10 m s⁻²)',
  options: ['800√2 N', '600 N', '800 N', '200√3 N'], answers: ['800 N'],
  figure: 'A roller on the ground is pushed by a force F directed downward along the handle, making 30° with the horizontal.',
  solution: 'The push has a downward component, so N = mg + F sin30° = 700 + 100 = 800 N.' },
{ id: 'main-2023-01-31-s1-Q4', number: 4, subject: 'Physics', chapter: 'Laws of Motion', topic: 'Conservation of Linear Momentum and Impulse', pattern: 'Force on wall from many rebounding balls', type: 'single', difficulty: 'Easy',
  question: '100 balls each of mass m moving with speed v simultaneously strike a wall normally and reflected back with same speed, in time t s. The total force exerted by the balls on the wall is',
  options: ['100mv/t', '200mv/t', '200 mvt', 'mv/(100t)'], answers: ['200mv/t'],
  solution: 'Each ball changes momentum by 2mv, so F = 100 × 2mv/t = 200mv/t.' },
{ id: 'main-2023-01-31-s1-Q5', number: 5, subject: 'Physics', chapter: 'Gravitation', topic: 'Acceleration due to Gravity and Its Variation', pattern: 'Depth where g equals g at a height', type: 'single', difficulty: 'Medium',
  question: 'At a certain depth d below surface of earth, the value of acceleration due to gravity becomes four times that at a height 3R above earth surface. Where R is the radius of earth (Take R = 6400 km). The depth d is equal to',
  options: ['5260 km', '640 km', '2560 km', '4800 km'], answers: ['4800 km'],
  solution: 'At height 3R, g′ = g/16; at depth d, g(1 − d/R) = 4g/16 = g/4, so d = 3R/4 = 4800 km.' },
{ id: 'main-2023-01-31-s1-Q6', number: 6, subject: 'Physics', chapter: 'Kinematics', topic: 'Equations of Motion in a Straight Line', pattern: 'Free fall independent of material', type: 'single', difficulty: 'Easy',
  question: 'Spherical insulating ball and a spherical metallic ball of same size and mass are dropped from the same height. Choose the correct statement out of the following (assume negligible air friction):',
  options: ['Time taken by them to reach the earth\'s surface will be independent of the properties of their materials', 'Insulating ball will reach the earth\'s surface earlier than the metal ball', 'Both will reach the earth\'s surface simultaneously', 'Metal ball will reach the earth\'s surface earlier than the insulating ball'], answers: ['Both will reach the earth\'s surface simultaneously'],
  solution: 'Without air resistance both fall with acceleration g, so they land together (the key marks option 3).' },
{ id: 'main-2023-01-31-s1-Q7', number: 7, subject: 'Physics', chapter: 'Mechanical Properties of Fluids', topic: 'Surface Tension, Surface Energy and Excess Pressure', pattern: 'Energy released on coalescence of droplets', type: 'single', difficulty: 'Medium',
  question: 'If 1000 droplets of water of surface tension 0.07 N m⁻¹, having same radius 1 mm each, combine to form a single drop. In the process the released surface energy is (Take π = 22/7)',
  options: ['7.92 × 10⁻⁶ J', '7.92 × 10⁻⁴ J', '9.68 × 10⁻⁴ J', '8.8 × 10⁻⁵ J'], answers: ['7.92 × 10⁻⁴ J'],
  solution: 'Big drop radius R = 10 mm; ΔE = 4πT(1000r² − R²) = 4πT(1000 − 100)×10⁻⁶ = 4×(22/7)×0.07×9×10⁻⁴ = 7.92×10⁻⁴ J.' },
{ id: 'main-2023-01-31-s1-Q8', number: 8, subject: 'Physics', chapter: 'Thermodynamics', topic: 'Isothermal and Adiabatic Processes', pattern: 'Internal energy change in adiabatic process from P-V graph', type: 'single', difficulty: 'Medium',
  question: 'The pressure of a gas changes linearly with volume from A to B as shown in figure. If no heat is supplied to or extracted from the gas then change in the internal energy of the gas will be',
  options: ['6 J', 'Zero', '-4.5 J', '4.5 J'], answers: ['4.5 J'],
  figure: 'P-V graph (P in kPa, V in cc): straight line from A (200 cc, 10 kPa) to B (50 cc, 50 kPa), arrow pointing from A to B.',
  solution: 'Q = 0 so ΔU = −W; the gas is compressed with work done on it = area = ½(10+50)×10³ × 150×10⁻⁶ = 4.5 J, so ΔU = +4.5 J.' },
{ id: 'main-2023-01-31-s1-Q9', number: 9, subject: 'Physics', chapter: 'Kinetic Theory of Gases', topic: 'Degrees of Freedom and Law of Equipartition of Energy', pattern: 'Temperature dependence of γ for ideal gas', type: 'single', difficulty: 'Easy',
  question: 'The correct relation between γ = C_P/C_V and temperature T is:',
  options: ['γ ∝ 1/√T', 'γ ∝ T⁰', 'γ ∝ 1/T', 'γ ∝ T'], answers: ['γ ∝ T⁰'],
  solution: 'For an ideal gas γ = 1 + 2/f depends only on degrees of freedom, not on T.' },
{ id: 'main-2023-01-31-s1-Q10', number: 10, subject: 'Physics', chapter: 'Oscillations (SHM)', topic: 'Velocity, Acceleration and Energy in SHM', pattern: 'Kinetic energy at half amplitude', type: 'single', difficulty: 'Easy',
  question: 'The maximum potential energy of a block executing simple harmonic motion is 25 J. A is amplitude of oscillation. At A/2, the kinetic energy of the block is',
  options: ['37.5 J', '9.75 J', '18.75 J', '12.5 J'], answers: ['18.75 J'],
  solution: 'KE = E(1 − x²/A²) = 25 × (1 − 1/4) = 18.75 J.' },
{ id: 'main-2023-01-31-s1-Q11', number: 11, subject: 'Physics', chapter: 'Electrostatic Potential and Capacitance', topic: 'Potential of Dipoles and Shells, Equipotential Surfaces', pattern: 'V-r graph of charged conducting sphere', type: 'single', difficulty: 'Easy',
  question: 'Which of the following correctly represents the variation of electric potential (V) of a charged spherical conductor of radius (R) with radial distance (r) from the centre?',
  options: ['V rises linearly from 0 to a peak at r = R, then falls as 1/r', 'V is zero inside, jumps at r = R, then falls as 1/r', 'V constant for r ≤ R, then falls as 1/r', 'V falls as 1/r from r = 0 continuously'], answers: ['V constant for r ≤ R, then falls as 1/r'],
  figure: 'Four V-versus-r graphs with R marked on the r-axis: (1) linear rise to peak at R then decay; (2) zero until R then a jump and decay; (3) flat up to R then decay; (4) decaying curve throughout.',
  solution: 'A conductor is an equipotential, so V is constant inside and equal to its surface value, then falls as kq/r outside.' },
{ id: 'main-2023-01-31-s1-Q12', number: 12, subject: 'Physics', chapter: 'Current Electricity', topic: 'Electric Current, Drift Velocity and Ohm\'s Law', pattern: 'Drift velocity vs cross-section at fixed voltage', type: 'single', difficulty: 'Easy',
  question: 'The drift velocity of electrons for a conductor connected in an electrical circuit is V_d. The conductor is now replaced by another conductor with same material and same length but double the area of cross-section. The applied voltage remains same. The new drift velocity of electrons will be',
  options: ['V_d', 'V_d/2', 'V_d/4', '2V_d'], answers: ['V_d'],
  solution: 'v_d = eEτ/m with E = V/l unchanged for the same material, length and voltage, so v_d stays V_d.' },
{ id: 'main-2023-01-31-s1-Q13', number: 13, subject: 'Physics', chapter: 'Magnetism and Matter', topic: 'Magnetic Dipole in a Uniform Magnetic Field', pattern: 'Work to turn magnet from stable to unstable equilibrium', type: 'single', difficulty: 'Easy',
  question: 'A bar magnet with a magnetic moment 5.0 A m² is placed in parallel position relative to a magnetic field of 0.4 T. The amount of required work done in turning the magnet from parallel to antiparallel position relative to the field direction is ________.',
  options: ['4 J', '1 J', '2 J', 'Zero'], answers: ['4 J'],
  solution: 'W = 2MB = 2 × 5 × 0.4 = 4 J.' },
{ id: 'main-2023-01-31-s1-Q14', number: 14, subject: 'Physics', chapter: 'Magnetism and Matter', topic: 'Magnetisation, Magnetic Intensity and Susceptibility', pattern: 'Relative permeability of solenoid core from flux', type: 'single', difficulty: 'Medium',
  question: 'A rod with circular cross-section area 2 cm² and length 40 cm is wound uniformly with 400 turns of an insulated wire. If a current of 0.4 A flows in the wire windings, the total magnetic flux produced inside windings is 4π × 10⁻⁶ Wb. The relative permeability of the rod is (Given: permeability of vacuum μ₀ = 4π × 10⁻⁷ N A⁻²)',
  options: ['12.5', '32/5', '125', '5/16'], answers: ['125'],
  solution: 'Φ = μ₀μ_r n I A with n = 1000 m⁻¹: 4π×10⁻⁶ = 4π×10⁻⁷ × μ_r × 1000 × 0.4 × 2×10⁻⁴, giving μ_r = 125.' },
{ id: 'main-2023-01-31-s1-Q15', number: 15, subject: 'Physics', chapter: 'Wave Optics', topic: 'Polarisation: Malus\' Law and Brewster\'s Law', pattern: 'Intensity through crossed polaroids with one in between', type: 'single', difficulty: 'Easy',
  question: 'Two polaroids A and B are placed in such a way that the pass-axis of polaroids are perpendicular to each other. Now, another polaroid C is placed between A and B bisecting angle between them. If intensity of unpolarised light is I₀ then intensity of transmitted light after passing through polaroid B will be:',
  options: ['I₀/4', 'I₀/2', 'I₀/8', 'Zero'], answers: ['I₀/8'],
  solution: 'After A: I₀/2; after C (45°): I₀/4; after B (45° again): I₀/8.' },
{ id: 'main-2023-01-31-s1-Q16', number: 16, subject: 'Physics', chapter: 'Dual Nature of Radiation and Matter', topic: 'de Broglie Wavelength and Matter Waves', pattern: 'Assertion-reason on wave nature of electrons', type: 'single', difficulty: 'Easy',
  question: 'Given below are two statements: Assertion A: The beam of electrons shows wave nature and exhibit interference and diffraction. Reason R: Davisson Germer Experimentally verified the wave nature of electrons. In the light of the above statements, choose the most appropriate answer from the options given below:',
  options: ['A is correct but R is not correct', 'A is not correct but R is correct', 'Both A and R are correct but R is Not the correct explanation of A', 'Both A and R are correct and R is the correct explanation of A'], answers: ['Both A and R are correct and R is the correct explanation of A'],
  solution: 'Electron diffraction in the Davisson-Germer experiment is the evidence for their wave nature, so R explains A.' },
{ id: 'main-2023-01-31-s1-Q17', number: 17, subject: 'Physics', chapter: 'Electromagnetic Waves', topic: 'Electromagnetic Spectrum', pattern: 'Photon energy from power and rate to EM region', type: 'single', difficulty: 'Medium',
  question: 'If a source of electromagnetic radiation having power 15 kW produces 10¹⁶ photons per second, the radiation belongs to a part of spectrum is: (Take Planck constant h = 6 × 10⁻³⁴ J s)',
  options: ['Micro waves', 'Ultraviolet rays', 'Gamma rays', 'Radio waves'], answers: ['Gamma rays'],
  solution: 'E = 15×10³/10¹⁶ = 1.5×10⁻¹² J, ν = E/h = 2.5×10²¹ Hz, which lies in the gamma-ray region.' },
{ id: 'main-2023-01-31-s1-Q18', number: 18, subject: 'Physics', chapter: 'Nuclei', topic: 'Alpha, Beta and Gamma Decay', pattern: 'Why a free neutron decays but a free proton does not', type: 'single', difficulty: 'Easy',
  question: 'A free neutron decays into a proton but a free proton does not decay into neutron. This is because',
  options: ['neutron is an uncharged particle', 'proton is a charged particle', 'neutron is a composite particle made of a proton and an electron', 'neutron has larger rest mass than proton'], answers: ['neutron has larger rest mass than proton'],
  solution: 'Decay needs the products to have less total mass than the parent; the neutron is heavier than the proton, the reverse is not allowed.' },
{ id: 'main-2023-01-31-s1-Q19', number: 19, subject: 'Physics', chapter: 'Semiconductor Electronics', topic: 'Intrinsic and Extrinsic Semiconductors', pattern: 'Temperature effect on carriers and resistance of semiconductor', type: 'single', difficulty: 'Easy',
  question: 'The effect of increase in temperature on the number of electrons in conduction band (n_e) and resistance of a semiconductor will be as:',
  options: ['Both n_e and resistance decrease', 'Both n_e and resistance increase', 'n_e increases, resistance decreases', 'n_e decreases, resistance increases'], answers: ['n_e increases, resistance decreases'],
  solution: 'Heating excites more electrons across the gap, so n_e rises and resistance falls.' },
{ id: 'main-2023-01-31-s1-Q20', number: 20, subject: 'Physics', chapter: 'Electromagnetic Waves', topic: 'Properties of Electromagnetic Waves', pattern: 'Frequencies present in an amplitude-modulated signal', type: 'single', difficulty: 'Medium',
  question: 'The amplitude of 15 sin(1000πt) is modulated by 10 sin(4πt) signal. The amplitude modulated signal contains frequency(ies) of (A) 500 Hz (B) 2 Hz (C) 250 Hz (D) 498 Hz (E) 502 Hz. Choose the correct answer from the options given below:',
  options: ['A only', 'A, D and E only', 'B only', 'A and B only'], answers: ['A, D and E only'],
  solution: 'Carrier f_c = 500 Hz, modulating f_m = 2 Hz, so the AM wave has f_c, f_c − f_m and f_c + f_m = 500, 498, 502 Hz.' },
{ id: 'main-2023-01-31-s1-Q21', number: 21, subject: 'Physics', chapter: 'Kinematics', topic: 'Relative Velocity and River-Boat Problems', pattern: 'River speed from drift of a swimmer', type: 'numerical', difficulty: 'Easy',
  question: 'The speed of a swimmer is 4 km h⁻¹ in still water. If the swimmer makes his strokes normal to the flow of river of width 1 km, he reaches a point 750 m down the stream on the opposite bank. The speed of the river water is ______ km h⁻¹.',
  answers: ['3'], solution: 'Crossing time = 1/4 h; drift 0.75 km in that time gives river speed = 0.75/(1/4) = 3 km h⁻¹.' },
{ id: 'main-2023-01-31-s1-Q22', number: 22, subject: 'Physics', chapter: 'Work, Energy and Power', topic: 'Kinetic Energy and the Work-Energy Theorem', pattern: 'Kinetic energy of lift after slipping fall', type: 'numerical', difficulty: 'Easy',
  question: 'A lift of mass M = 500 kg is descending with speed of 2 m s⁻¹. Its supporting cable begins to slip thus allowing it to fall with a constant acceleration of 2 m s⁻². The kinetic energy of the lift at the end of fall through a distance of 6 m will be ______ kJ.',
  answers: ['7'], solution: 'v² = 2² + 2×2×6 = 28, KE = ½×500×28 = 7000 J = 7 kJ.' },
{ id: 'main-2023-01-31-s1-Q23', number: 23, subject: 'Physics', chapter: 'Rotational Motion', topic: 'Rolling Motion', pattern: 'Speed of rolling sphere from its kinetic energy', type: 'numerical', difficulty: 'Easy',
  question: 'A solid sphere of mass 1 kg rolls without slipping on a plane surface. Its kinetic energy is 7 × 10⁻³ J. The speed of the centre of mass of the sphere is ______ cm s⁻¹.',
  answers: ['10'], solution: 'KE = (7/10)mv² = 7×10⁻³ gives v² = 0.01, v = 0.1 m/s = 10 cm/s.' },
{ id: 'main-2023-01-31-s1-Q24', number: 24, subject: 'Physics', chapter: 'Mechanical Properties of Solids', topic: 'Thermal Stress, Own-Weight Elongation and Applications', pattern: 'Mass hung to restore length after cooling', type: 'numerical', difficulty: 'Medium',
  question: 'A thin rod having a length of 1 m and area of cross-section 3 × 10⁻⁶ m² is suspended vertically from one end. The rod is cooled from 210°C to 160°C. After cooling, a mass M is attached at the lower end of the rod such that the length of rod again becomes 1 m. Young\'s modulus and coefficient of linear expansion of the rod are 2 × 10¹¹ N m⁻² and 2 × 10⁻⁵ K⁻¹, respectively. The value of M is ______ kg. (Take g = 10 m s⁻²)',
  answers: ['60'], solution: 'Mg = YAαΔT = 2×10¹¹ × 3×10⁻⁶ × 2×10⁻⁵ × 50 = 600 N, so M = 60 kg.' },
{ id: 'main-2023-01-31-s1-Q25', number: 25, subject: 'Physics', chapter: 'Oscillations (SHM)', topic: 'Spring-Mass Systems', pattern: 'Oscillation count of block between two springs', type: 'numerical', difficulty: 'Easy',
  question: 'In the figure given below, a block of mass M = 490 g placed on a frictionless table is connected with two springs having same spring constant (K = 2 N m⁻¹). If the block is horizontally displaced through X m then the number of complete oscillations it will make in 14π seconds will be ______.',
  figure: 'Block of mass M between two walls, joined to each wall by a spring of constant K.',
  answers: ['20'], solution: 'k_eff = 2K = 4 N/m, T = 2π√(0.49/4) = 0.7π s, so oscillations = 14π/0.7π = 20.' },
{ id: 'main-2023-01-31-s1-Q26', number: 26, subject: 'Physics', chapter: 'Electric Charges and Fields', topic: 'Electric Flux and Gauss\'s Law', pattern: 'Flux of non-uniform field through a cube', type: 'numerical', difficulty: 'Medium',
  question: 'Expression for an electric field is given by E = 4000x² î V m⁻¹. The electric flux through the cube of side 20 cm when placed in electric field (as shown in the figure) is ______ V cm.',
  figure: 'Cube of side 20 cm with one corner at the origin, edges along +x, +y, +z; field along x.',
  answers: ['640'], solution: 'Only faces at x = 0 (E = 0) and x = 20 cm contribute: E = 4000×0.04 = 160 V/m, flux = 160 × 0.04 = 6.4 V m = 640 V cm.' },
{ id: 'main-2023-01-31-s1-Q27', number: 27, subject: 'Physics', chapter: 'Current Electricity', topic: 'EMF, Internal Resistance and Combination of Cells', pattern: 'Same current for cells in series and parallel', type: 'numerical', difficulty: 'Easy',
  question: 'Two identical cells, when connected either in parallel or in series gives same current in an external resistance 5 Ω. The internal resistance of each cell will be ______ Ω.',
  answers: ['5'], solution: '2E/(2r+R) = E/(r/2+R) gives r = R = 5 Ω.' },
{ id: 'main-2023-01-31-s1-Q28', number: 28, subject: 'Physics', chapter: 'Alternating Current', topic: 'Resonance and Quality Factor', pattern: 'Peak current at resonance in series LCR', type: 'numerical', difficulty: 'Easy',
  question: 'An inductor of 0.5 mH, a capacitor of 20 μF and resistance of 20 Ω are connected in series with a 220 V ac source. If the current is in phase with the emf, the amplitude of current of the circuit is √x A. The value of x is ______.',
  answers: ['242'], solution: 'In phase means resonance, so I₀ = √2 × 220/20 = 11√2 A, hence x = 242.' },
{ id: 'main-2023-01-31-s1-Q29', number: 29, subject: 'Physics', chapter: 'Electromagnetic Waves', topic: 'Properties of Electromagnetic Waves', pattern: 'Refractive index/dielectric constant from wave speed', type: 'numerical', difficulty: 'Easy',
  question: 'In a medium the speed of light decreases to 0.2 times its speed in free space. The ratio of relative permittivity to the refractive index of the medium is x : 1. The value of x is ______. (Given speed of light in free space = 3 × 10⁸ m s⁻¹ and for the given medium μ_r = 1)',
  answers: ['5'], solution: 'n = 1/0.2 = 5 and n² = ε_r μ_r gives ε_r = 25, so ε_r : n = 5 : 1.' },
{ id: 'main-2023-01-31-s1-Q30', number: 30, subject: 'Physics', chapter: 'Atoms', topic: 'Hydrogen Spectrum and Spectral Series', pattern: 'Ratio of wavelengths of hydrogen transitions', type: 'numerical', difficulty: 'Medium',
  question: 'For hydrogen atom, λ₁ and λ₂ are the wavelengths corresponding to the transitions 1 and 2 respectively as shown in figure. The ratio of λ₁ and λ₂ is x/32. The value of x is ______.',
  figure: 'Energy levels n = 1, 2, 3. Transition 1 is from n = 3 to n = 1; transition 2 is from n = 2 to n = 1.',
  answers: ['27'], solution: '1/λ₁ = R(1 − 1/9) = 8R/9 and 1/λ₂ = 3R/4, so λ₁/λ₂ = (3/4)/(8/9) = 27/32.' },
{ id: 'main-2023-01-31-s1-Q31', number: 31, subject: 'Chemistry', chapter: 'Structure of Atom', topic: 'Hydrogen Spectrum', pattern: 'Equal wavelength transition in H and He⁺', type: 'single', difficulty: 'Medium',
  question: 'Which transition in the hydrogen spectrum would have the same wavelength as the Balmer type transition from n = 4 to n = 2 of He⁺ spectrum?',
  options: ['n = 2 to n = 1', 'n = 1 to n = 3', 'n = 1 to n = 2', 'n = 3 to n = 4'], answers: ['n = 2 to n = 1'],
  solution: 'For He⁺ (Z = 2): 1/λ = 4R(1/4 − 1/16) = 3R/4, which equals R(1/1² − 1/2²) of hydrogen, i.e. n = 2 to 1.' },
{ id: 'main-2023-01-31-s1-Q32', number: 32, subject: 'Chemistry', chapter: 'Periodic Properties', topic: 'Atomic and Ionic Radii', pattern: 'Isoelectronic radii and halogen electron gain order', type: 'single', difficulty: 'Easy',
  question: 'The correct increasing order of the ionic radii is',
  options: ['Cl⁻ < Ca²⁺ < K⁺ < S²⁻', 'K⁺ < S²⁻ < Ca²⁺ < Cl⁻', 'S²⁻ < Cl⁻ < Ca²⁺ < K⁺', 'Ca²⁺ < K⁺ < Cl⁻ < S²⁻'], answers: ['Ca²⁺ < K⁺ < Cl⁻ < S²⁻'],
  solution: 'These are isoelectronic (18 e⁻); radius decreases with increasing nuclear charge: Ca²⁺ < K⁺ < Cl⁻ < S²⁻.' },
{ id: 'main-2023-01-31-s1-Q33', number: 33, subject: 'Chemistry', chapter: 'Chemical Bonding', topic: 'VSEPR Theory and Molecular Shapes', pattern: 'Match molecules with their shapes', type: 'single', difficulty: 'Easy',
  question: 'Match List I with List II. List I: A. XeF₄ B. SF₄ C. NH₄⁺ D. BrF₃. List II: I. See-saw II. Square planar III. Bent T-shaped IV. Tetrahedral. Choose the correct answer from the options given below:',
  options: ['A - IV, B - III, C - II, D - I', 'A - II, B - I, C - III, D - IV', 'A - IV, B - I, C - II, D - III', 'A - II, B - I, C - IV, D - III'], answers: ['A - II, B - I, C - IV, D - III'],
  solution: 'XeF₄ is square planar, SF₄ see-saw, NH₄⁺ tetrahedral, BrF₃ bent T-shaped.' },
{ id: 'main-2023-01-31-s1-Q34', number: 34, subject: 'Chemistry', chapter: 'Redox Reactions', topic: 'Oxidation, Reduction and Redox Agents', pattern: 'Identify reaction where H₂O₂ is the reducing agent', type: 'single', difficulty: 'Medium',
  question: 'H₂O₂ acts as a reducing agent in',
  options: ['2NaOCl + H₂O₂ → 2NaCl + H₂O + O₂', '2Fe²⁺ + 2H⁺ + H₂O₂ → 2Fe³⁺ + 2H₂O', 'Mn²⁺ + 2H₂O₂ → MnO₂ + 2H₂O', 'Na₂S + 4H₂O₂ → Na₂SO₄ + 4H₂O'], answers: ['2NaOCl + H₂O₂ → 2NaCl + H₂O + O₂'],
  solution: 'H₂O₂ is reducing only when it is oxidised to O₂, which happens in the NaOCl reaction; in the others it is reduced to H₂O.' },
{ id: 'main-2023-01-31-s1-Q35', number: 35, subject: 'Chemistry', chapter: 'Organic Chemistry - Basic Principles', topic: 'Purification of Organic Compounds', pattern: 'Match mixtures with separation techniques', type: 'single', difficulty: 'Medium',
  question: 'Match items of column I and II. Column I (mixture): A. H₂O / CH₂Cl₂ B. a mixture of a bicyclic ketone and 4-nitrophenol (structures shown) C. Kerosene / Naphthalene D. C₆H₁₂O₆ / NaCl. Column II (separation technique): i. Crystallization ii. Differential solvent extraction iii. Column chromatography iv. Fractional distillation.',
  options: ['A - (iii), B - (iv), C - (ii), D - (i)', 'A - (ii), B - (iii), C - (iv), D - (i)', 'A - (i), B - (iii), C - (ii), D - (iv)', 'A - (ii), B - (i), C - (iv), D - (iii)'], answers: ['A - (ii), B - (iii), C - (iv), D - (i)'],
  figure: 'B shows a bicyclic ketone (tetralone-type) together with 4-nitrophenol.',
  solution: 'Immiscible water/CH₂Cl₂ use solvent extraction, similar-polarity organics use column chromatography, kerosene/naphthalene use fractional distillation, glucose/NaCl use crystallization.' },
{ id: 'main-2023-01-31-s1-Q36', number: 36, subject: 'Chemistry', chapter: 'Hydrocarbons', topic: 'Reactions of Alkenes', pattern: 'Convert trans-alkene to cis-alkene via alkyne', type: 'single', difficulty: 'Medium',
  question: 'Choose the correct set of reagents for the following conversion: trans Ph-CH=CH-CH₃ → cis Ph-CH=CH-CH₃',
  options: ['Br₂, alc KOH, NaNH₂, NaLiqNH₃', 'Br₂, alc KOH, NaNH₂, H₂ Lindlar Catalyst', 'Br₂, aq KOH, NaNH₂, H₂ Lindlar Catalyst', 'Br₂, aq KOH, NaNH₂, NaLiqNH₃'], answers: ['Br₂, alc KOH, NaNH₂, H₂ Lindlar Catalyst'],
  solution: 'Bromination gives the vicinal dibromide, alc KOH/NaNH₂ eliminates twice to the alkyne, and Lindlar hydrogenation gives the cis alkene.' },
{ id: 'main-2023-01-31-s1-Q37', number: 37, subject: 'Chemistry', chapter: 'Electrochemistry', topic: 'Electrolysis and Faraday\'s Laws', pattern: 'Products of electrolysis of aqueous electrolytes', type: 'single', difficulty: 'Easy',
  question: 'Which one of the following statements is correct for electrolysis of brine solution?',
  options: ['Cl₂ is formed at cathode', 'O₂ is formed at cathode', 'H₂ is formed at anode', 'OH⁻ is formed at cathode'], answers: ['OH⁻ is formed at cathode'],
  solution: 'At the cathode water is reduced: 2H₂O + 2e⁻ → H₂ + 2OH⁻; Cl₂ forms at the anode.' },
{ id: 'main-2023-01-31-s1-Q38', number: 38, subject: 'Chemistry', chapter: 'Solutions', topic: 'Solubility and Henry\'s Law', pattern: 'Reverse micelle structure in non-polar solvent', type: 'single', difficulty: 'Medium',
  question: 'Adding surfactants in non polar solvent, the micelles structure will look like (four diagrams a, b, c, d are given).',
  options: ['b', 'c', 'a', 'd'], answers: ['a'],
  figure: 'Four boxes labelled "Non Polar Solvent" showing surfactant molecules: (a) and (b) radial arrangements of surfactant chains in a sphere, (c) and (d) layered/bilayer-like arrangements of chains.',
  solution: 'In a non-polar solvent surfactants form reverse micelles with polar heads inward and hydrocarbon tails towards the solvent, shown in diagram (a) per the key.' },
{ id: 'main-2023-01-31-s1-Q39', number: 39, subject: 'Chemistry', chapter: 'd- and f-Block Elements', topic: 'Electronic Configuration and General Characteristics', pattern: 'Methods not used in ore concentration', type: 'single', difficulty: 'Medium',
  question: 'The methods NOT involved in concentration of ore are (A) Liquation (B) Leaching (C) Electrolysis (D) Hydraulic washing (E) Froth floatation. Choose the correct answer from the options given below:',
  options: ['B, D and C only', 'C, D and E only', 'A and C only', 'B, D and E only'], answers: ['A and C only'],
  solution: 'Hydraulic washing, froth floatation and leaching concentrate ores; liquation (refining) and electrolysis (refining/extraction) are not concentration methods.' },
{ id: 'main-2023-01-31-s1-Q40', number: 40, subject: 'Chemistry', chapter: 'p-Block Elements (Groups 15-18)', topic: 'Interhalogen Compounds and Oxoacids of Halogens', pattern: 'Hydrolysis of chlorine nitrate', type: 'single', difficulty: 'Medium',
  question: 'Identify X, Y and Z in the following reaction (equation not balanced): ClO + NO₂ → X, then X + H₂O → Y + Z',
  options: ['X = ClONO₂, Y = HOCl, Z = NO₂', 'X = ClNO₂, Y = HCl, Z = HNO₃', 'X = ClONO₂, Y = HOCl, Z = HNO₃', 'X = ClNO₃, Y = Cl₂, Z = NO₂'], answers: ['X = ClONO₂, Y = HOCl, Z = HNO₃'],
  solution: 'ClO + NO₂ gives chlorine nitrate ClONO₂, which hydrolyses to HOCl and HNO₃.' },
{ id: 'main-2023-01-31-s1-Q41', number: 41, subject: 'Chemistry', chapter: 'd- and f-Block Elements', topic: 'Oxidation States and Electrode Potentials', pattern: 'Cu²⁺ with KI then thiosulphate titration', type: 'single', difficulty: 'Easy',
  question: 'When Cu²⁺ ion is treated with KI, a white precipitate X appears in solution. The solution is titrated with sodium thiosulphate, the compound Y is formed. X and Y respectively are',
  options: ['X = Cu₂I₂, Y = Na₂S₄O₅', 'X = Cu₂I₂, Y = Na₂S₄O₆', 'X = CuI₂, Y = Na₂S₄O₃', 'X = CuI, Y = Na₂S₄O₆'], answers: ['X = Cu₂I₂, Y = Na₂S₄O₆'],
  solution: '2Cu²⁺ + 4I⁻ → Cu₂I₂ (white) + I₂; the liberated I₂ oxidises thiosulphate to tetrathionate Na₂S₄O₆.' },
{ id: 'main-2023-01-31-s1-Q42', number: 42, subject: 'Chemistry', chapter: 'd- and f-Block Elements', topic: 'Oxidation States and Electrode Potentials', pattern: 'Basicity order of vanadium oxides', type: 'single', difficulty: 'Easy',
  question: 'The correct order of basicity of oxides of vanadium is',
  options: ['V₂O₃ > V₂O₄ > V₂O₅', 'V₂O₃ > V₂O₅ > V₂O₄', 'V₂O₅ > V₂O₄ > V₂O₃', 'V₂O₄ > V₂O₃ > V₂O₅'], answers: ['V₂O₃ > V₂O₄ > V₂O₅'],
  solution: 'Basic character falls as the oxidation state of the metal rises: V₂O₃ (+3) > V₂O₄ (+4) > V₂O₅ (+5, amphoteric/acidic).' },
{ id: 'main-2023-01-31-s1-Q43', number: 43, subject: 'Chemistry', chapter: 'd- and f-Block Elements', topic: 'Lanthanoids and Lanthanoid Contraction', pattern: 'f-electron configuration of lanthanoid ions', type: 'single', difficulty: 'Easy',
  question: 'The electronic configuration of Nd²⁺ is',
  options: ['4f²6s²', '4f⁴', '4f³', '4f⁴6s²'], answers: ['4f⁴'],
  solution: 'Nd is [Xe]4f⁴6s²; losing the two 6s electrons gives [Xe]4f⁴.' },
{ id: 'main-2023-01-31-s1-Q44', number: 44, subject: 'Chemistry', chapter: 'Coordination Compounds', topic: 'Spectrochemical Series, Colour and Magnetism', pattern: 'Pink and blue cobalt chloride complexes and geometry', type: 'single', difficulty: 'Easy',
  question: 'Cobalt chloride when dissolved in water forms pink coloured complex X which has octahedral geometry. This solution on treating with conc. HCl forms deep blue complex, Y which has a Z geometry. X, Y and Z, respectively, are',
  options: ['X = [Co(H₂O)₆]²⁺, Y = [CoCl₄]²⁻, Z = Tetrahedral', 'X = [Co(H₂O)₆]²⁺, Y = [CoCl₆]³⁻, Z = Octahedral', 'X = [Co(H₂O)₆]³⁺, Y = [CoCl₆]³⁻, Z = Octahedral', 'X = [Co(H₂O)₄Cl₂]⁺, Y = [CoCl₄]²⁻, Z = Tetrahedral'], answers: ['X = [Co(H₂O)₆]²⁺, Y = [CoCl₄]²⁻, Z = Tetrahedral'],
  solution: 'Pink [Co(H₂O)₆]²⁺ converts with conc. HCl to blue tetrahedral [CoCl₄]²⁻.' },
{ id: 'main-2023-01-31-s1-Q45', number: 45, subject: 'Chemistry', chapter: 'Haloalkanes and Haloarenes', topic: 'Physical Properties and Nature of C–X Bond', pattern: 'Melting point order of dichlorobenzene isomers', type: 'single', difficulty: 'Easy',
  question: 'The correct order of melting point of dichlorobenzenes is',
  options: ['para > meta > ortho', 'ortho > meta > para', 'meta > para > ortho', 'para > ortho > meta'], answers: ['para > ortho > meta'],
  figure: 'Each option shows structures of 1,4- (para), 1,3- (meta) and 1,2- (ortho) dichlorobenzene in a different order; the options here are written as the orders depicted.',
  solution: 'Para is most symmetric and packs best (highest mp); ortho has higher mp than meta, giving para > ortho > meta.' },
{ id: 'main-2023-01-31-s1-Q46', number: 46, subject: 'Chemistry', chapter: 'Alcohols, Phenols and Ethers', topic: 'Reactions of Phenols', pattern: 'Bromination of phenol in low polarity solvent', type: 'single', difficulty: 'Easy',
  question: 'An organic compound A with empirical formula C₆H₆O gives sooty flame on burning. Its reaction with bromine solution in low polarity solvent results in high yield of B. B is',
  options: ['4-bromophenol', 'a dihydrofuran bearing a CH₂CH₂Br group', 'a dibromo tetrahydrofuran bearing an ethyl group', '2-bromophenol'], answers: ['4-bromophenol'],
  figure: 'Option 1: para-bromophenol; option 2: a dihydrofuran bearing CH₂CH₂Br; option 3: a dibromo tetrahydrofuran bearing ethyl; option 4: ortho-bromophenol.',
  solution: 'A is phenol; Br₂ in a low-polarity solvent such as CS₂ gives mono-bromination, mainly the para product.' },
{ id: 'main-2023-01-31-s1-Q47', number: 47, subject: 'Chemistry', chapter: 'Aldehydes, Ketones and Carboxylic Acids', topic: 'Aldol, Cannizzaro and Related Reactions', pattern: 'Aldol then cyanohydrin and hydrolysis to hydroxy acid', type: 'single', difficulty: 'Hard',
  question: 'Consider the following reaction: Propanal + Methanal → (i) dil. NaOH (ii) Δ (iii) NaCN (iv) H₃O⁺ → Product B (C₅H₈O₃). The correct statement for product B is. It is',
  options: ['optically active and adds one mole of bromine', 'racemic mixture and is neutral', 'racemic mixture and gives a gas with saturated NaHCO₃ solution', 'optically active alcohol and is neutral'], answers: ['racemic mixture and gives a gas with saturated NaHCO₃ solution'],
  solution: 'Aldol condensation gives CH₂=C(CH₃)CHO; NaCN adds to give the cyanohydrin and H₃O⁺ hydrolyses it to a chiral hydroxy acid (racemic), which releases CO₂ with NaHCO₃.' },
{ id: 'main-2023-01-31-s1-Q48', number: 48, subject: 'Chemistry', chapter: 'Amines', topic: 'Reactions of Amines: Acylation, Carbylamine and Nitrous Acid', pattern: 'Nitrobenzene reduction then acetylation', type: 'single', difficulty: 'Easy',
  question: 'Nitrobenzene is treated with H₂/Pd in C₂H₅OH to give [A], which is then treated with (CH₃CO)₂O in pyridine to give [B]. B is',
  options: ['C₆H₅CH₂CONH₂', 'C₆H₅COCH₂NH₂', 'C₆H₅NHCH₂CONH₂', 'C₆H₅NHCOCH₃'], answers: ['C₆H₅NHCOCH₃'],
  solution: 'H₂/Pd reduces nitrobenzene to aniline, which is acetylated by acetic anhydride to acetanilide.' },
{ id: 'main-2023-01-31-s1-Q49', number: 49, subject: 'Chemistry', chapter: 'Biomolecules', topic: 'Carbohydrates and the Structure of Glucose', pattern: 'Artificial sweetener with highest sweetness value', type: 'single', difficulty: 'Easy',
  question: 'Which of the following artificial sweeteners has the highest sweetness value in comparison to cane sugar?',
  options: ['Aspartame', 'Sucralose', 'Alitame', 'Saccharin'], answers: ['Alitame'],
  solution: 'Alitame is about 2000 times sweeter than cane sugar, more than aspartame (100), sucralose (600) and saccharin (550).' },
{ id: 'main-2023-01-31-s1-Q50', number: 50, subject: 'Chemistry', chapter: 'Biomolecules', topic: 'Amino Acids and Proteins', pattern: 'Facts about specific amino acids', type: 'single', difficulty: 'Medium',
  question: 'A protein X with molecular weight of 70,000 u, on hydrolysis gives amino acids. One of these amino acid is',
  options: ['NH₂–CH₂–CH(CH₃)–CH₂CH₂COOH', '(CH₃)₂CH–CH₂–CH(NH₂)–COOH', '(CH₃)₂CH–CH(NH₂)–CH₂CH₂COOH', '(CH₃)₂C(NH₂)–CH₂–CH₂COOH'], answers: ['(CH₃)₂CH–CH₂–CH(NH₂)–COOH'],
  figure: 'Four structures; option 2 is the α-amino acid with an isobutyl side chain (leucine); the others have the amino group away from the α-carbon.',
  solution: 'Proteins hydrolyse to α-amino acids only; option 2 is leucine (NH₂ on the carbon next to COOH).' },
{ id: 'main-2023-01-31-s1-Q51', number: 51, subject: 'Chemistry', chapter: 'Organic Chemistry - Basic Principles', topic: 'Qualitative and Quantitative Analysis', pattern: '% carbon from CO₂ in combustion', type: 'numerical', difficulty: 'Easy',
  question: 'On complete combustion, 0.492 g of an organic compound gave 0.792 g of CO₂. The % of carbon in the organic compound is (nearest integer)',
  answers: ['44'], solution: '% C = (12/44) × 0.792/0.492 × 100 = 43.9, i.e. 44.' },
{ id: 'main-2023-01-31-s1-Q52', number: 52, subject: 'Chemistry', chapter: 'Some Basic Concepts (Mole Concept)', topic: 'Stoichiometry and Limiting Reagent', pattern: 'Products from metal + excess acid', type: 'numerical', difficulty: 'Easy',
  question: 'Zinc reacts with hydrochloric acid to give hydrogen and zinc chloride. The volume of hydrogen gas produced at STP from the reaction of 11.5 g of zinc with excess HCl is ______ L (nearest integer). (Given: molar mass of Zn is 65.4 g mol⁻¹ and molar volume of H₂ at STP = 22.7 L)',
  answers: ['4'], solution: 'Moles Zn = 11.5/65.4 = 0.176 = moles H₂; volume = 0.176 × 22.7 ≈ 4 L.' },
{ id: 'main-2023-01-31-s1-Q53', number: 53, subject: 'Chemistry', chapter: 'Chemical Thermodynamics', topic: 'Thermochemistry and Hess\'s Law', pattern: 'Enthalpy of Cl⁻(aq) formation from half Cl₂', type: 'numerical', difficulty: 'Medium',
  question: 'The enthalpy change for the conversion of ½Cl₂(g) to Cl⁻(aq) is (−) ______ kJ mol⁻¹ (nearest integer). Given: Δ_dis H°(Cl₂(g)) = 240 kJ mol⁻¹, Δ_eg H°(Cl(g)) = −350 kJ mol⁻¹, Δ_hyd H°(Cl⁻(g)) = −380 kJ mol⁻¹',
  answers: ['610'], solution: 'ΔH = ½(240) + (−350) + (−380) = −610 kJ mol⁻¹.' },
{ id: 'main-2023-01-31-s1-Q54', number: 54, subject: 'Chemistry', chapter: 'Chemical Equilibrium', topic: 'Kp, Kc and Manipulating K', pattern: 'Find Δn from Kp/Kc ratio', type: 'numerical', difficulty: 'Medium',
  question: 'For reaction: SO₂(g) + ½O₂(g) ⇌ SO₃(g), K_p = 2 × 10¹² at 27°C and 1 atm pressure. The K_c for the same reaction is ______ × 10¹³. (nearest integer) (Given R = 0.082 L atm K⁻¹ mol⁻¹)',
  answers: ['1'], solution: 'Δn = −½, so K_c = K_p(RT)^{1/2} = 2×10¹² × √24.6 ≈ 9.9×10¹² ≈ 1×10¹³.' },
{ id: 'main-2023-01-31-s1-Q55', number: 55, subject: 'Chemistry', chapter: 'Gaseous State', topic: 'Dalton\'s Law of Partial Pressures', pattern: 'Partial pressure from masses and molar masses', type: 'numerical', difficulty: 'Easy',
  question: 'The total pressure of a mixture of non-reacting gases X (0.6 g) and Y (0.45 g) in a vessel is 740 mm of Hg. The partial pressure of the gas X is ______ mm of Hg. (nearest integer) (Given: molar mass X = 20 and Y = 45 g mol⁻¹)',
  answers: ['555'], solution: 'Moles X = 0.03, Y = 0.01, so x_X = 0.75 and p_X = 0.75 × 740 = 555 mm Hg.' },
{ id: 'main-2023-01-31-s1-Q56', number: 56, subject: 'Chemistry', chapter: 'Solutions', topic: 'Osmosis and Osmotic Pressure', pattern: 'Molar mass from osmotic pressure', type: 'numerical', difficulty: 'Medium',
  question: 'At 27°C, a solution containing 2.5 g of solute in 250.0 mL of solution exerts an osmotic pressure of 400 Pa. The molar mass of the solute is ______ g mol⁻¹. (nearest integer) (Given: R = 0.083 L bar K⁻¹ mol⁻¹)',
  answers: ['62250'], solution: 'π = 0.004 bar; n = πV/RT = 0.004×0.25/(0.083×300) = 4.016×10⁻⁵ mol, so M = 2.5/4.016×10⁻⁵ ≈ 62250 g/mol.' },
{ id: 'main-2023-01-31-s1-Q57', number: 57, subject: 'Chemistry', chapter: 'Electrochemistry', topic: 'Gibbs Energy, Cell Potential and Equilibrium Constant', pattern: 'log K from standard potentials of complex formation', type: 'numerical', difficulty: 'Medium',
  question: 'The logarithm of equilibrium constant for the reaction Pd²⁺ + 4Cl⁻ ⇌ PdCl₄²⁻ is ______ (nearest integer). Given: 2.303RT/F = 0.06 V; Pd²⁺(aq) + 2e⁻ ⇌ Pd(s), E° = 0.83 V; PdCl₄²⁻(aq) + 2e⁻ ⇌ Pd(s) + 4Cl⁻(aq), E° = 0.65 V',
  answers: ['6'], solution: 'Cell reaction E° = 0.83 − 0.65 = 0.18 V, so log K = nE°/0.06 = 2×0.18/0.06 = 6.' },
{ id: 'main-2023-01-31-s1-Q58', number: 58, subject: 'Chemistry', chapter: 'Chemical Kinetics', topic: 'Temperature Dependence: Arrhenius Equation', pattern: 'Activation energy from rate constants at two temperatures', type: 'numerical', difficulty: 'Medium',
  question: 'A → B. The rate constants of the above reaction at 200 K and 300 K are 0.03 min⁻¹ and 0.05 min⁻¹ respectively. The activation energy for the reaction is ______ J (nearest integer). (Given: ln 10 = 2.3, R = 8.3 J K⁻¹ mol⁻¹, log 5 = 0.70, log 3 = 0.48, log 2 = 0.30)',
  answers: ['2520'], solution: 'Ea = 2.3R log(k₂/k₁) × T₁T₂/(T₂−T₁) = 2.3×8.3×0.22×600 ≈ 2520 J.' },
{ id: 'main-2023-01-31-s1-Q59', number: 59, subject: 'Chemistry', chapter: 'p-Block Elements (Groups 15-18)', topic: 'Oxoacids of Phosphorus', pattern: 'Oxidation state of phosphorus in hypophosphoric acid', type: 'numerical', difficulty: 'Easy',
  question: 'The oxidation state of phosphorus in hypophosphoric acid is ______.',
  answers: ['4'], solution: 'Hypophosphoric acid is H₄P₂O₆: 4 + 2x − 12 = 0 gives x = +4.' },
{ id: 'main-2023-01-31-s1-Q60', number: 60, subject: 'Chemistry', chapter: 'Amines', topic: 'Classification and Preparation of Amines', pattern: 'Count transformations giving aromatic amines', type: 'numerical', difficulty: 'Medium',
  question: 'How many of the transformations given below would result in aromatic amines? (1) benzamide + Br₂ + NaOH; (2) potassium phthalimide + chlorobenzene; (3) m-nitro-substituted benzene (NO₂ on ring) with H₂/Pd-C; (4) acetanilide with dil. H₂SO₄, Δ',
  answers: ['3'], solution: 'Hofmann bromamide, nitro reduction and acetanilide hydrolysis give aryl amines; Gabriel synthesis fails with aryl halides, so 3.' },
{ id: 'main-2023-01-31-s1-Q61', number: 61, subject: 'Mathematics', chapter: 'Quadratic Equations', topic: 'Equations Reducible to Quadratics', pattern: 'Count real roots of equation with radicals', type: 'single', difficulty: 'Hard',
  question: 'The number of real roots of the equation √(x² − 4x + 3) + √(x² − 9) = √(4x² − 14x + 6), is:',
  options: ['0', '1', '3', '2'], answers: ['1'],
  solution: 'Factorise: √((x−1)(x−3)) + √((x−3)(x+3)) = √(2(2x−1)(x−3)); x = 3 works, and squaring for x > 3 and x ≤ −3 gives x = 1 and x = 7/6, both rejected, so one root.' },
{ id: 'main-2023-01-31-s1-Q62', number: 62, subject: 'Mathematics', chapter: 'Complex Numbers', topic: 'Geometry of Complex Numbers: Loci and Rotation', pattern: 'Locus of z + 1/z for |z| = constant', type: 'single', difficulty: 'Medium',
  question: 'For all z ∈ C on the curve C₁: |z| = 4, let the locus of the point z + 1/z be the curve C₂. Then',
  options: ['the curves C₁ and C₂ intersect at 4 points', 'the curves C₁ lies inside C₂', 'the curves C₁ and C₂ intersect at 2 points', 'the curves C₂ lies inside C₁'], answers: ['the curves C₁ and C₂ intersect at 4 points'],
  solution: 'With z = 4e^{iθ}, C₂ is the ellipse with semi-axes 17/4 and 15/4; the circle of radius 4 lies between them and meets the ellipse at 4 points.' },
{ id: 'main-2023-01-31-s1-Q63', number: 63, subject: 'Mathematics', chapter: 'Sequences and Series', topic: 'Geometric Progression', pattern: 'GP terms from sum and product conditions', type: 'single', difficulty: 'Hard',
  question: 'If the sum and product of four positive consecutive terms of a G.P., are 126 and 1296, respectively, then the sum of common ratios of all such GPs is',
  options: ['7', '9/2', '3', '14'], answers: ['7'],
  solution: 'Take terms t/s³, t/s, ts, ts³: t⁴ = 1296 gives t = 6 and s + 1/s + s³ + 1/s³ = 21 gives s + 1/s = 3; the two ratios s² and 1/s² sum to 3² − 2 = 7.' },
{ id: 'main-2023-01-31-s1-Q64', number: 64, subject: 'Mathematics', chapter: 'Circles', topic: 'Tangents and Normals to a Circle', pattern: 'Rolling circle and reflected circle, trapezium area', type: 'single', difficulty: 'Hard',
  question: 'Let a circle C₁ be obtained on rolling the circle x² + y² − 4x − 6y + 11 = 0 upwards 4 units on the tangent T to it at the point (3, 2). Let C₂ be the image of C₁ in T. Let A and B be the centers of circles C₁ and C₂ respectively, and let M and N be respectively the feet of perpendiculars drawn from A and B on the x-axis. Then the area of the trapezium AMNB is:',
  options: ['2(2 + √2)', '4(1 + √2)', '3 + 2√2', '2(1 + √2)'], answers: ['4(1 + √2)'],
  solution: 'Centre (2,3), r = √2, T: x − y = 1. Rolling 4 units up T gives A = (2+2√2, 3+2√2); reflecting in T gives B = (4+2√2, 1+2√2); area = ½(AM+BN)·MN = ½(4+4√2)(2) = 4(1+√2).' },
{ id: 'main-2023-01-31-s1-Q65', number: 65, subject: 'Mathematics', chapter: 'Conic Sections', topic: 'Normals to Conics', pattern: 'Eccentricity from maximum distance of normal from origin', type: 'single', difficulty: 'Hard',
  question: 'If the maximum distance of normal to the ellipse x²/4 + y²/b² = 1, b < 2, from the origin is 1, then the eccentricity of the ellipse is:',
  options: ['1/√2', '√3/2', '1/2', '√3/4'], answers: ['√3/2'],
  solution: 'The maximum distance of a normal from the centre is a − b = 2 − b = 1, so b = 1 and e = √(1 − 1/4) = √3/2.' },
{ id: 'main-2023-01-31-s1-Q66', number: 66, subject: 'Mathematics', chapter: 'Sets', topic: 'Sets, Their Representation and Types', pattern: 'Tautology and contradiction of compound statements', type: 'single', difficulty: 'Medium',
  question: 'Consider: S1: (p ⇒ q) ∨ (p ∧ ~q) is a tautology. S2: (~p ⇒ ~q) ∧ (~p ∧ q) is a contradiction. Then',
  options: ['only S2 is correct', 'both S1 and S2 are correct', 'both S1 and S2 are wrong', 'only S1 is correct'], answers: ['only S1 is correct'],
  solution: 'S1 is true whether p is true (q or ~q) or false, so it is a tautology; S2 reduces to ~p ∧ q, which is true for p = F, q = T, so it is not a contradiction.' },
{ id: 'main-2023-01-31-s1-Q67', number: 67, subject: 'Mathematics', chapter: 'Relations and Functions', topic: 'Types of Relations', pattern: 'Check reflexive/symmetric/transitive', type: 'single', difficulty: 'Medium',
  question: 'Let R be a relation on N × N defined by (a, b) R (c, d) if and only if ad(b − c) = bc(a − d). Then R is',
  options: ['symmetric but neither reflexive nor transitive', 'transitive but neither reflexive nor symmetric', 'reflexive and symmetric but not transitive', 'symmetric and transitive but not reflexive'], answers: ['symmetric but neither reflexive nor transitive'],
  solution: 'The condition simplifies to 1/a + 1/c = 1/b + 1/d. It is symmetric by interchanging (a,b) and (c,d); reflexivity needs a = b, which fails in general; and transitivity also fails in general.' },
{ id: 'main-2023-01-31-s1-Q68', number: 68, subject: 'Mathematics', chapter: 'Matrices', topic: 'Powers of Matrices and Special Matrices', pattern: 'Trace of (A+I)ⁿ via eigenvalues of a matrix', type: 'single', difficulty: 'Medium',
  question: 'Let A = [[1, 0, 0], [0, 4, −1], [0, 12, −3]]. Then the sum of the diagonal elements of the matrix (A + I)¹¹ is equal to:',
  options: ['6144', '4094', '4097', '2050'], answers: ['4097'],
  solution: 'The 2×2 block has trace 1 and det 0, so eigenvalues 0 and 1; A has eigenvalues 1, 1, 0 and A + I has 2, 2, 1, so the trace of (A+I)¹¹ is 2¹¹ + 2¹¹ + 1 = 4097.' },
{ id: 'main-2023-01-31-s1-Q69', number: 69, subject: 'Mathematics', chapter: 'Determinants', topic: 'Consistency and Homogeneous Systems', pattern: 'Consistency conditions of a 3×3 system with parameters', type: 'single', difficulty: 'Hard',
  question: 'For the system of linear equations x + y + z = 6, αx + βy + 7z = 3, x + 2y + 3z = 14, which of the following is NOT true?',
  options: ['If α = β = 7, then the system has no solution', 'If α = β and α ≠ 7 then the system has a unique solution.', 'There is a unique point (α, β) on the line x + 2y + 18 = 0 for which the system has infinitely many solutions', 'For every point (α, β) ≠ (7, 7) on the line x − 2y + 7 = 0, the system has infinitely many solutions.'], answers: ['For every point (α, β) ≠ (7, 7) on the line x − 2y + 7 = 0, the system has infinitely many solutions.'],
  solution: 'Δ = 0 gives the line α − 2β + 7 = 0 through (7,7); on it the system is consistent only at the single point (−25/2, −11/4) (which lies on x + 2y + 18 = 0), so statement 4 is false.' },
{ id: 'main-2023-01-31-s1-Q70', number: 70, subject: 'Mathematics', chapter: 'Inverse Trigonometric Functions', topic: 'Compositions: sin⁻¹(sin x) and sin(cos⁻¹x)', pattern: 'Solve inverse-trig sum for α then evaluate principal values', type: 'single', difficulty: 'Hard',
  question: 'If sin⁻¹(α/17) + cos⁻¹(4/5) − tan⁻¹(77/36) = 0, 0 < α < 13, then sin⁻¹(sin α) + cos⁻¹(cos α) is equal to',
  options: ['π', '16', '0', '16 − 5π'], answers: ['π'],
  solution: 'tan⁻¹(77/36) − tan⁻¹(3/4) = tan⁻¹(8/15) = sin⁻¹(8/17), so α = 8; sin⁻¹(sin 8) = 3π − 8 and cos⁻¹(cos 8) = 8 − 2π, summing to π.' },
{ id: 'main-2023-01-31-s1-Q71', number: 71, subject: 'Mathematics', chapter: 'Conic Sections', topic: 'Parabola', pattern: 'Parabola equation then inverse-trig equation solutions', type: 'single', difficulty: 'Hard',
  question: 'Let y = f(x) represent a parabola with focus (−1/2, 0) and directrix y = −1/2. Then S = {x ∈ R : tan⁻¹√f(x) + sin⁻¹√(f(x) + 1) = π/2}:',
  options: ['contains exactly two elements', 'contains exactly one element', 'is an infinite set', 'is an empty set'], answers: ['contains exactly two elements'],
  solution: 'Equating focus and directrix distances gives f(x) = x² + x. The equation forces √(f+1) = 1/√(f+1), so f = 0, i.e. x = 0 or −1: two elements.' },
{ id: 'main-2023-01-31-s1-Q72', number: 72, subject: 'Mathematics', chapter: 'Relations and Functions', topic: 'One-one, Onto and Bijective Functions', pattern: 'Range of greatest-integer rational function on an interval', type: 'single', difficulty: 'Medium',
  question: 'If the domain of the function f(x) = [x]/(1 + x²), where [x] is greatest integer ≤ x, is [2, 6), then its range is',
  options: ['(5/26, 2/5] − {9/29, 27/109, 18/89, 9/53}', '(5/26, 2/5]', '(5/37, 2/5] − {9/29, 27/109, 18/89, 9/53}', '(5/37, 2/5]'], answers: ['(5/37, 2/5]'],
  solution: 'On [2,3),[3,4),[4,5),[5,6) the values lie in (1/5,2/5], (3/17,3/10], (2/13,4/17], (5/37,5/26]; these overlap to give (5/37, 2/5] (2/5 attained at x = 2, 5/37 not attained).' },
{ id: 'main-2023-01-31-s1-Q73', number: 73, subject: 'Mathematics', chapter: 'Continuity and Differentiability', topic: 'Chain Rule and Derivatives of Inverse Trigonometric Functions', pattern: 'Nested trigonometric derivative at a point', type: 'single', difficulty: 'Hard',
  question: 'Let y = f(x) = sin³((π/3) cos((π/(3√2))(−4x³ + 5x² + 1)^{3/2})). Then, at x = 1,',
  options: ['2y′ + √3π²y = 0', '2y′ + 3π²y = 0', '√2y′ − 3π²y = 0', 'y′ + 3π²y = 0'], answers: ['2y′ + 3π²y = 0'],
  solution: 'At x = 1 the inner bracket is 2, giving angles 2π/3, then −π/6, so y = −1/8; the chain rule gives y′ = 3π²/16, hence 2y′ + 3π²y = 3π²/8 − 3π²/8 = 0.' },
{ id: 'main-2023-01-31-s1-Q74', number: 74, subject: 'Mathematics', chapter: 'Application of Derivatives', topic: 'Optimisation Problems', pattern: 'Minimise weighted sum of square and circle areas from a wire', type: 'single', difficulty: 'Medium',
  question: 'A wire of length 20 m is to be cut into two pieces. A piece of length ℓ₁ is bent to make a square of area A₁ and the other piece of length ℓ₂ is made into a circle of area A₂. If 2A₁ + 3A₂ is minimum then πℓ₁ : ℓ₂ is equal to:',
  options: ['6 : 1', '3 : 1', '1 : 6', '4 : 1'], answers: ['6 : 1'],
  solution: 'f = ℓ₁²/8 + 3ℓ₂²/(4π) with ℓ₁ + ℓ₂ = 20; f′ = 0 gives ℓ₁/4 = 3ℓ₂/(2π), i.e. πℓ₁ = 6ℓ₂.' },
{ id: 'main-2023-01-31-s1-Q75', number: 75, subject: 'Mathematics', chapter: 'Definite Integrals and Area Under Curves', topic: 'Fundamental Theorem and Evaluation', pattern: 'Integral of t^n/(1−t) in terms of a truncated log series', type: 'single', difficulty: 'Medium',
  question: 'Let α ∈ (0, 1) and β = logₑ(1 − α). Let P_n(x) = x + x²/2 + x³/3 + … + xⁿ/n, x ∈ (0, 1). Then the integral ∫₀^α t⁵⁰/(1 − t) dt is equal to',
  options: ['β − P₅₀(α)', '−(β + P₅₀(α))', 'P₅₀(α) − β', 'β + P₅₀(α)'], answers: ['−(β + P₅₀(α))'],
  solution: 't⁵⁰/(1−t) = 1/(1−t) − (1 + t + … + t⁴⁹), so the integral is −logₑ(1−α) − P₅₀(α) = −(β + P₅₀(α)).' },
{ id: 'main-2023-01-31-s1-Q76', number: 76, subject: 'Mathematics', chapter: 'Definite Integrals and Area Under Curves', topic: 'Fundamental Theorem and Evaluation', pattern: 'Trigonometric integral via half-angle substitution', type: 'single', difficulty: 'Hard',
  question: 'The value of ∫ from π/3 to π/2 of (2 + 3 sin x)/(sin x (1 + cos x)) dx is equal to',
  options: ['7/2 − √3 − logₑ√3', '−2 + 3√3 + logₑ√3', '10/3 − √3 + logₑ√3', '10/3 − √3 − logₑ√3'], answers: ['10/3 − √3 + logₑ√3'],
  solution: 'With t = tan(x/2) the integrand becomes (1/t + t + 3)dt on [1/√3, 1], giving logₑ√3 + 1/3 + (3 − √3) = 10/3 − √3 + logₑ√3.' },
{ id: 'main-2023-01-31-s1-Q77', number: 77, subject: 'Mathematics', chapter: 'Definite Integrals and Area Under Curves', topic: 'Leibniz Rule and Integral Functions', pattern: 'Integral equation solved by differentiation', type: 'single', difficulty: 'Medium',
  question: 'Let f be a differentiable function satisfying f(x) + ∫₃ˣ f(t)/t dt = √(x + 1), x ≥ 3. Then 12f(8) is equal to:',
  options: ['34', '19', '17', '1'], answers: ['17'],
  solution: 'Differentiating, (xf)′ = x/(2√(x+1)), so xf = (x+1)^{3/2}/3 − √(x+1) + C; f(3) = 2 gives C = 16/3, so 8f(8) = 34/3 and 12f(8) = 17.' },
{ id: 'main-2023-01-31-s1-Q78', number: 78, subject: 'Mathematics', chapter: 'Vector Algebra', topic: 'Scalar (Dot) Product and Projection', pattern: 'Statements from equal-magnitude vector sums and orthogonality', type: 'single', difficulty: 'Medium',
  question: 'Let a = 2î + ĵ + k̂, and b and c be two nonzero vectors such that |a + b + c| = |a + b − c| and b · c = 0. Consider the following two statements: (A) |a + λc| ≥ |a| for all λ ∈ R. (B) a and c are always parallel.',
  options: ['only (B) is correct', 'neither (A) nor (B) is correct', 'only (A) is correct', 'both (A) and (B) are correct.'], answers: ['only (A) is correct'],
  solution: 'The first condition gives (a + b)·c = 0 and with b·c = 0, a·c = 0; then |a + λc|² = |a|² + λ²|c|² ≥ |a|², so A holds, while a ⊥ c means B is false.' },
{ id: 'main-2023-01-31-s1-Q79', number: 79, subject: 'Mathematics', chapter: 'Three Dimensional Geometry', topic: 'Angle Between Lines and Shortest Distance', pattern: 'Shortest distance between skew lines fixes parameter', type: 'single', difficulty: 'Hard',
  question: 'Let the shortest distance between the lines L: (x − 5)/(−2) = (y − λ)/0 = (z + λ)/1, λ ≥ 0 and L₁: x + 1 = y − 1 = 4 − z be 2√6. If (α, β, γ) lies on L, then which of the following is NOT possible?',
  options: ['α + 2γ = 24', '2α + γ = 7', '2α − γ = 9', 'α − 2γ = 19'], answers: ['α + 2γ = 24'],
  solution: 'Shortest distance = |λ + 3|/√6 = 2√6 gives λ = 9; points of L are (5 − 2t, 9, t − 9) so α + 2γ = −13 always, and 24 is impossible.' },
{ id: 'main-2023-01-31-s1-Q80', number: 80, subject: 'Mathematics', chapter: 'Probability', topic: 'Total Probability and Bayes\' Theorem', pattern: 'Bayes with uniform prior on bag composition', type: 'single', difficulty: 'Medium',
  question: 'A bag contains 6 balls. Two balls are drawn from it at random and both are found to be black. The probability that the bag contains at least 5 black balls is',
  options: ['5/7', '2/7', '3/7', '5/6'], answers: ['5/7'],
  solution: 'With equal priors for 2..6 black balls, likelihoods ∝ C(i,2) = 1, 3, 6, 10, 15 (sum 35); P(at least 5) = (10 + 15)/35 = 5/7.' },
{ id: 'main-2023-01-31-s1-Q81', number: 81, subject: 'Mathematics', chapter: 'Permutations and Combinations', topic: 'Permutations with Repetition and Dictionary Rank', pattern: 'Serial number of a number in ascending order of digit strings', type: 'numerical', difficulty: 'Medium',
  question: 'Let 5 digit numbers be constructed using the digits 0, 2, 3, 4, 7, 9 with repetition allowed, and are arranged in ascending order with serial numbers. Then the serial number of the number 42923 is ______.',
  answers: ['2997'], solution: 'Numbers before it: first digit 2 or 3: 2×6⁴ = 2592; 40xxx: 216; 42 then third digit < 9: 5×36 = 180; 429 then fourth < 2: 6; 4292 then fifth < 3: 2; total 2996, so rank 2997.' },
{ id: 'main-2023-01-31-s1-Q82', number: 82, subject: 'Mathematics', chapter: 'Sequences and Series', topic: 'Method of Differences and Telescoping Series', pattern: 'Telescoping reciprocal sum of surds in AP', type: 'numerical', difficulty: 'Medium',
  question: 'Let a₁, a₂, …, aₙ be in A.P. If a₅ = 2a₇ and a₁₁ = 18, then 12[1/(√a₁₀ + √a₁₁) + 1/(√a₁₁ + √a₁₂) + … + 1/(√a₁₇ + √a₁₈)] is equal to ______.',
  answers: ['8'], solution: 'a₅ = 2a₇ gives a = −8d and a₁₁ = 2d = 18, so d = 9; the sum telescopes to (12/d)(√a₁₈ − √a₁₀) = (12/9)(9 − 3) = 8.' },
{ id: 'main-2023-01-31-s1-Q83', number: 83, subject: 'Mathematics', chapter: 'Permutations and Combinations', topic: 'Fundamental Principle of Counting', pattern: 'Four-digit numbers up to N divisible by 3 or 11', type: 'numerical', difficulty: 'Medium',
  question: 'Number of 4-digit numbers that are less than or equal to 2800 and either divisible by 3 or by 11, is equal to ______.',
  answers: ['710'], solution: 'Between 1000 and 2800: multiples of 3 = 933 − 333 = 600, of 11 = 254 − 90 = 164, of 33 = 84 − 30 = 54; total 600 + 164 − 54 = 710.' },
{ id: 'main-2023-01-31-s1-Q84', number: 84, subject: 'Mathematics', chapter: 'Binomial Theorem', topic: 'Term Independent of x and Coefficient of a Given Power', pattern: 'Smallest negative exponent in a binomial expansion', type: 'numerical', difficulty: 'Medium',
  question: 'Let α > 0, be the smallest number such that the expansion of (x^{2/3} + 2/x³)³⁰ has a term βx^{−α}, β ∈ N. Then α is equal to ______.',
  answers: ['2'], solution: 'General term has exponent 20 − 11r/3 with r a multiple of 3 for integral power; r = 3 gives 9, r = 6 gives −2, so the smallest α > 0 is 2.' },
{ id: 'main-2023-01-31-s1-Q85', number: 85, subject: 'Mathematics', chapter: 'Binomial Theorem', topic: 'Remainders, Divisibility and Multinomial Expansion', pattern: 'Remainder of a large power', type: 'numerical', difficulty: 'Easy',
  question: 'The remainder on dividing 5⁹⁹ by 11 is ______.',
  answers: ['9'], solution: '5⁵ ≡ 1 (mod 11), so 5⁹⁹ = (5⁵)¹⁹·5⁴ ≡ 625 ≡ 9.' },
{ id: 'main-2023-01-31-s1-Q86', number: 86, subject: 'Mathematics', chapter: 'Statistics', topic: 'Variance and Standard Deviation', pattern: 'Missing frequency from given variance', type: 'numerical', difficulty: 'Medium',
  question: 'If the variance of the frequency distribution x_i = 2, 3, 4, 5, 6, 7, 8 with frequencies f_i = 3, 6, 16, α, 9, 5, 6 is 3, then α is equal to ______.',
  answers: ['5'], solution: 'With n = 45 + α, Σfx = 225 + 5α and Σfx² = 1275 + 25α; α = 5 gives mean 5 and variance 1400/50 − 25 = 3.' },
{ id: 'main-2023-01-31-s1-Q87', number: 87, subject: 'Mathematics', chapter: 'Definite Integrals and Area Under Curves', topic: 'Area Between Two Curves', pattern: 'Area bounded by composite piecewise function and a line', type: 'numerical', difficulty: 'Hard',
  question: 'Let for x ∈ R, f(x) = (x + |x|)/2 and g(x) = x for x < 0, x² for x ≥ 0. Then area bounded by the curve y = (f∘g)(x) and the lines y = 0, 2y − x = 15 is equal to ______.',
  answers: ['72'], solution: 'f∘g = 0 for x < 0 and x² for x ≥ 0. Area = ∫₋₁₅⁰ (x+15)/2 dx + ∫₀³ ((x+15)/2 − x²) dx = 225/4 + 99/4 − 9 = 72.' },
{ id: 'main-2023-01-31-s1-Q88', number: 88, subject: 'Mathematics', chapter: 'Vector Algebra', topic: 'Vector (Cross) Product and Area', pattern: 'Dot product squared from magnitudes and cross product', type: 'numerical', difficulty: 'Easy',
  question: 'Let a and b be two vector such that |a| = √14, |b| = √6 and |a × b| = √48. Then (a · b)² is equal to ______.',
  answers: ['36'], solution: '|a×b|² + (a·b)² = |a|²|b|² gives (a·b)² = 84 − 48 = 36.' },
{ id: 'main-2023-01-31-s1-Q89', number: 89, subject: 'Mathematics', chapter: 'Three Dimensional Geometry', topic: 'Line and Plane: Intersection, Angle, Foot and Image', pattern: 'Line meets plane, foot of perpendicular, triangle', type: 'numerical', difficulty: 'Hard',
  question: 'Let the line L: (x − 1)/2 = (y + 1)/(−1) = (z − 3)/1 intersect the plane 2x + y + 3z = 16 at the point P. Let the point Q be the foot of perpendicular from the point R(1, −1, −3) on the line L. If α is the area of triangle PQR, then α² is equal to ______.',
  answers: ['180'], solution: 'P = (3, −2, 4) (t = 1) and Q = (−1, 0, 2) (t = −1); PQ × QR = (12, 24, 0) so area² = 720/4 = 180.' },
{ id: 'main-2023-01-31-s1-Q90', number: 90, subject: 'Mathematics', chapter: 'Three Dimensional Geometry', topic: 'Angle, Distance and Family of Planes', pattern: 'Angle between planes and line-plane angle relation', type: 'numerical', difficulty: 'Medium',
  question: 'Let θ be the angle between the planes P₁: r·(î + ĵ + 2k̂) = 9 and P₂: r·(2î − ĵ + k̂) = 15. Let L be the line that meets P₂ at the point (4, −2, 5) and makes an angle θ with the normal of P₂. If α is the angle between L and P₂ then tan²θ cot²α is equal to ______.',
  answers: ['9'], solution: 'cosθ = 3/6 gives θ = 60°; the line makes θ with the normal so α = 90° − θ = 30°, hence tan²60° cot²30° = 3 × 3 = 9.' },
] };
